ALTER TABLE projects ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE milestones ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tracker_outbox ADD COLUMN organization TEXT NOT NULL DEFAULT '';
UPDATE tracker_outbox SET organization=COALESCE((SELECT json_extract(config,'$.org_header') || ':' || json_extract(config,'$.org_id') FROM tracker_connection WHERE id='tracker' AND json_extract(config,'$.org_id')!=''),'');
CREATE TABLE tracker_publications(id TEXT PRIMARY KEY,local_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,selection_id TEXT NOT NULL,queue TEXT NOT NULL,organization TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',external_id TEXT NOT NULL DEFAULT '',issue_key TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '');
INSERT INTO tracker_publications(id,local_id,project_id,selection_id,queue,organization,state) SELECT id,local_id,COALESCE(project_id,''),selection_id,payload,organization,'outcome_unknown' FROM tracker_outbox WHERE kind='publish';
CREATE TRIGGER projects_revision AFTER UPDATE OF name,slug,description,color,icon,sort_order ON projects WHEN OLD.name IS NOT NEW.name OR OLD.slug IS NOT NEW.slug OR OLD.description IS NOT NEW.description OR OLD.color IS NOT NEW.color OR OLD.icon IS NOT NEW.icon OR OLD.sort_order IS NOT NEW.sort_order BEGIN UPDATE projects SET revision=OLD.revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER milestones_revision AFTER UPDATE OF project_id,title,description,milestone_type,version,planned_date,completed_date,status,owner,external_url ON milestones WHEN OLD.project_id IS NOT NEW.project_id OR OLD.title IS NOT NEW.title OR OLD.description IS NOT NEW.description OR OLD.milestone_type IS NOT NEW.milestone_type OR OLD.version IS NOT NEW.version OR OLD.planned_date IS NOT NEW.planned_date OR OLD.completed_date IS NOT NEW.completed_date OR OLD.status IS NOT NEW.status OR OLD.owner IS NOT NEW.owner OR OLD.external_url IS NOT NEW.external_url BEGIN UPDATE milestones SET revision=OLD.revision+1 WHERE id=NEW.id; END;
